const isTrophy=f=>f.size>=(SPECIES.find(s=>s.name===f.name)?.trophy??Infinity);
function fishWeights(li,si,zone=null,precision=1){const habitat=[[1,1,1.4,1.3,1.4,.8],[1.1,1.4,.8,1.5,.8,1.4],[1.4,1,1.2,1,1,1],[1,1.5,1,1,1.3,1.3]][si];return lureWeights[li].map((v,i)=>v*(i===LURE_TARGET[li]?precision:1)*habitat[i]*(zone?.weights[i]||1)/SPECIES[i].coefficient)}
function fishChances(li,si,zone=null,precision=1){const w=fishWeights(li,si,zone,precision),total=w.reduce((a,b)=>a+b,0);return w.map(v=>v/total*100)}
function pickFish(li,si,random=Math.random,zone=null,precision=1){const weights=fishWeights(li,si,zone,precision);let draw=random()*weights.reduce((a,b)=>a+b,0);return SPECIES.find((s,i)=>weights[i]>0&&(draw-=weights[i])<0)||SPECIES[weights.findLastIndex(w=>w>0)]}
