// ===== Économie : progression jusqu'au niveau 250 =====
// Les gains grandissent avec le niveau pour que les bonus de plus en plus chers restent atteignables.
const coinScale=lv=>1+(Math.max(1,lv)-1)*.03;
const xpScale=lv=>1+(Math.max(1,lv)-1)*.035;
const levelXp=lv=>80*(Math.max(1,lv)-1)**2;
const effLevel=n=>n<=5?n:5+(n-5)*.5;   // canne / fil / chaussures : 10 niveaux, rendement décroissant après le 5e
const UPGRADE_TIERS=[{cost:60,level:1},{cost:240,level:3},{cost:540,level:6},{cost:960,level:10},{cost:1500,level:15},{cost:3200,level:30},{cost:7000,level:55},{cost:15000,level:85},{cost:32000,level:120},{cost:70000,level:170}];
// Qualité des leurres (boutique de pêche) : chaque palier débloque un niveau du joueur et améliore le leurre.
const LURE_TIERS=[
  {name:'Standard',level:1,cost:0,size:0,prec:1,bite:1,trophy:0},
  {name:'Pro',level:8,cost:300,size:.04,prec:1.15,bite:.97,trophy:0},
  {name:'Expert',level:25,cost:1500,size:.08,prec:1.3,bite:.94,trophy:.01},
  {name:'Maître',level:50,cost:6000,size:.12,prec:1.5,bite:.9,trophy:.02},
  {name:'Élite',level:90,cost:20000,size:.17,prec:1.7,bite:.86,trophy:.035},
  {name:'Légendaire',level:140,cost:60000,size:.22,prec:1.95,bite:.82,trophy:.05},
  {name:'Mythique',level:200,cost:160000,size:.28,prec:2.2,bite:.78,trophy:.07}
];
const LURE_SPECIALTY=['bite','coins','size','prec','trophy','xp'];   // un point fort par leurre
const LURE_EXTRA=[0,.03,.06,.09,.13,.17,.22];
function lureTierOf(owned,li){const e=owned.find(x=>typeof x==='string'&&x.startsWith('lure'+li+':'));return e?Math.max(0,Math.min(LURE_TIERS.length-1,Number(e.split(':')[1])||0)):0}
function lureBonus(li,tier){
  tier=Math.max(0,Math.min(LURE_TIERS.length-1,tier));const t=LURE_TIERS[tier],sp=LURE_SPECIALTY[li];
  return {size:t.size*(sp==='size'?1.25:1),prec:1+(t.prec-1)*(sp==='prec'?1.25:1),bite:1-(1-t.bite)*(sp==='bite'?1.5:1),trophy:t.trophy*(sp==='trophy'?1.5:1),coins:sp==='coins'?LURE_EXTRA[tier]:0,xp:sp==='xp'?LURE_EXTRA[tier]:0};
}

// Server derives the fishing zone from the cast coordinates, never a submitted zone ID.
function riverPosition(x,y){let total=0,best={distance:Infinity,s:0};for(let i=1;i<RIVER_COURSE.length;i++){const a=RIVER_COURSE[i-1],b=RIVER_COURSE[i],dx=(b[0]-a[0])*MAP_FACTOR,dy=(b[1]-a[1])*MAP_FACTOR,len=Math.hypot(dx,dy);const t=Math.max(0,Math.min(1,((x-a[0]*MAP_FACTOR)*dx+(y-a[1]*MAP_FACTOR)*dy)/(len*len||1)));const distance=Math.hypot(x-a[0]*MAP_FACTOR-t*dx,y-a[1]*MAP_FACTOR-t*dy);if(distance<best.distance)best={distance,s:total+t*len};total+=len}return{...best,fraction:best.s/total}}
function fishingZone(x,y){if(!Number.isFinite(x)||!Number.isFinite(y))return null;const p=riverPosition(x,y);return p.distance<=mapUnit(160)?FISH_ZONES.find(z=>Math.abs(p.fraction-z.at)<=z.span)||null:null}
