const FACTOR=MAP_FACTOR,RAW=RIVER_COURSE,route=[];
let LENGTH=0;RAW.forEach(([x,y],i)=>{x*=FACTOR;y*=FACTOR;if(i)LENGTH+=Math.hypot(x-route[i-1].x,y-route[i-1].y);route.push({x,y,s:LENGTH})});
function at(s){s=Math.max(0,Math.min(LENGTH,s));let lo=1,hi=route.length-1;while(lo<hi){const mid=(lo+hi)>>>1;if(route[mid].s<s)lo=mid+1;else hi=mid}const i=lo;let a=route[i-1],b=route[i],len=b.s-a.s,k=(s-a.s)/len,tx=(b.x-a.x)/len,ty=(b.y-a.y)/len;return{x:a.x+(b.x-a.x)*k,y:a.y+(b.y-a.y)*k,tx,ty,nx:-ty,ny:tx,s}}
function nearest(p){let best={d:Infinity,s:0,x:0,y:0};for(let i=1;i<route.length;i++){let a=route[i-1],b=route[i],dx=b.x-a.x,dy=b.y-a.y,k=Math.max(0,Math.min(1,((p.x-a.x)*dx+(p.y-a.y)*dy)/(dx*dx+dy*dy))),x=a.x+dx*k,y=a.y+dy*k,d=Math.hypot(p.x-x,p.y-y);if(d<best.d)best={d,s:a.s+(b.s-a.s)*k,x,y}}return best}
const association=VILLAGE.find(v=>v.id==='club');
const spawnPoint={x:association.doorX,y:association.doorY+mapUnit(26)};
function spawnAtAssociation(){
  const near=nearest(spawnPoint),normal=at(near.s);
  Object.assign(player,spawnPoint,{s:near.s,offset:(spawnPoint.x-near.x)*normal.nx+(spawnPoint.y-near.y)*normal.ny});
}
const START=nearest({x:730.5*FACTOR,y:507.5*FACTOR}).s,spots=[{s:mapUnit(100),name:'Moulin de Gazeau',type:'Courant · limite aval'},{s:START*.54,name:'Bois de la Sèvre',type:'Ombre et branches'},{s:START,name:'Site de Fleuriais',type:'Point de départ'},{s:LENGTH-mapUnit(120),name:'L’Escale des 2 Eaux',type:'Herbiers · limite amont'}],lures=LURES.map(l=>l.name),skinColors={olive:['#446748','#e1c79b'],blue:['#245981','#96e2e8'],red:['#b74433','#ffcd89'],gold:['#94722d','#ffe3a0'],champion:['#503681','#ffd345']};
