function placePlayer(){let p=at(player.s);player.x=p.x+p.nx*player.offset;player.y=p.y+p.ny*player.offset}spawnAtAssociation();camera={x:player.x,y:player.y};
const terrain=new Image();terrain.src=TERRAIN_SRC;let terrainReady=false;terrain.onload=()=>{terrainReady=true;detailTiles.clear();detailMips.clear()};const waterBits=Uint8Array.from(atob(WATER_MASK.bits),c=>c.charCodeAt(0));
function channelWater(p){const x=Math.floor(p.x/FACTOR/WATER_MASK.cell),y=Math.floor(p.y/FACTOR/WATER_MASK.cell);if(x<0||y<0||x>=WATER_MASK.w||y>=WATER_MASK.h)return false;const i=y*WATER_MASK.w+x;return !!(waterBits[i>>3]&(1<<(i&7)))}
// Bridge coordinates share the river's geometry and remain aligned at every zoom.
const bridges=[{s:START,name:'Pont de Fleuriais',halfLength:mapUnit(210),halfWidth:mapUnit(53)},{s:nearest({x:919*FACTOR,y:653*FACTOR}).s,name:'Pont D160',halfLength:mapUnit(245),halfWidth:mapUnit(64)}];
function bridgeLocal(p,b){const q=at(b.s),dx=p.x-q.x,dy=p.y-q.y;return{along:dx*q.nx+dy*q.ny,across:dx*q.tx+dy*q.ty}}
function onBridge(p,margin=0){return bridges.some(b=>{const q=bridgeLocal(p,b);return Math.abs(q.along)<=b.halfLength-margin&&Math.abs(q.across)<=b.halfWidth-margin})}
function isWater(p){return channelWater(p)&&!onBridge(p)}
const buildings=[];
function walkable(p){if(p.x<mapUnit(40)||p.y<mapUnit(40)||p.x>WORLD_WIDTH-mapUnit(40)||p.y>WORLD_HEIGHT-mapUnit(40))return false;if(onBridge(p,mapUnit(12)))return true;for(const d of [[0,0],[10,0],[-10,0],[0,10],[0,-10]])if(isWater({x:p.x+mapUnit(d[0]),y:p.y+mapUnit(d[1])}))return false;return true}
const rnd=n=>{let x=Math.sin(n*127.1+311.7)*43758.5453;return x-Math.floor(x)};
// Restore the last position accepted by the server, including after a reload.
function restoreServerPosition(position){
 if(!position||!Number.isFinite(position.x)||!Number.isFinite(position.y))return false;
 const saved={x:position.x,y:position.y};
 if(!walkable(saved))return false;
 const near=nearest(saved),normal=at(near.s);
 Object.assign(player,saved,{s:near.s,offset:(saved.x-near.x)*normal.nx+(saved.y-near.y)*normal.ny});
 camera={x:player.x,y:player.y};
 mapManual=false;
 return true;
}

let zoomIndex=8;const zooms=[.02,.05,.08,.16,.24,.36,.48,.68,.9,1.2,1.6,2.2,2.8,3.6];let zoomFollowDelay=0,mapManual=false;
function setMapZoom(value,anchor){
 const fixed=anchor?world(anchor.x,anchor.y):null;
 scale=Math.max(zooms[0],Math.min(zooms.at(-1),value));
 zoomIndex=zooms.reduce((best,z,i)=>Math.abs(z-scale)<Math.abs(zooms[best]-scale)?i:best,0);
 if(fixed){camera.x=fixed.x-(anchor.x-w/2)/scale;camera.y=fixed.y-(anchor.y-h*.5)/(scale*VT);zoomFollowDelay=.6}
 $('zoomOut').disabled=scale<=zooms[0];$('zoomIn').disabled=scale>=zooms.at(-1);
}
function changeZoom(d){if(!mapManual&&active)camera={x:player.x,y:player.y};const next=d>0?zooms.find(z=>z>scale+.00001):zooms.slice().reverse().find(z=>z<scale-.00001);setMapZoom(next??(d>0?zooms.at(-1):zooms[0]));}
$('zoomOut').onclick=()=>changeZoom(-1);$('zoomIn').onclick=()=>changeZoom(1);
function recenterMap(){cameraTween=null;cancelMapPointers();mapManual=false;zoomFollowDelay=0;camera={x:player.x,y:player.y}}
$('recenterMap').onclick=recenterMap;
function resize(){
 const frame=document.body;
 if(window.visualViewport&&frame){
  const height=Math.floor(window.visualViewport.height)+'px';
  if(frame.style.getPropertyValue('--game-visible-height')!==height)frame.style.setProperty('--game-visible-height',height);
 }
 w=frame?.clientWidth||innerWidth;
 h=frame?.clientHeight||innerHeight;
 const d=Math.min(devicePixelRatio,2);
 canvas.width=Math.round(w*d);canvas.height=Math.round(h*d);
 ctx.setTransform(d,0,0,d,0,0);
}
