const dist=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y);
let VT=1;   // 1 = vue de dessus ; <1 = caméra inclinée (vue 3D)
const sdist=(a,b)=>Math.hypot((a.x-b.x)*scale,(a.y-b.y)*scale*VT);function world(x,y){return{x:(x-w/2)/scale+camera.x,y:(y-h*.50)/(scale*VT)+camera.y}}function modal(){return document.querySelector('dialog[open]')}function hint(t){$('hint').hidden=false;$('hint').textContent=t}
function dismissWalkTip(){if($('hint').textContent==='Glisse pour marcher.')$('hint').hidden=true}
function closestSpot(s){let n=0;spots.forEach((p,i)=>{if(Math.abs(p.s-s)<Math.abs(spots[n].s-s))n=i});return n}
let gameAccountMode=null;
async function api(path,body){
  if(!gameAccountMode)throw new Error('Choisis Invité ou Compte du concours avant de jouer.');
  const token=gameAccountMode==='participant'?await window.participantToken():null;
  if(gameAccountMode==='participant'&&!token)throw Object.assign(new Error('Connecte-toi à ton compte sur la page du concours pour jouer en participant.'),{status:401});
  const controller=new AbortController();
  const timeout=setTimeout(()=>controller.abort(),15000);
  try{
    const response=await fetch('/jeu/api/'+path,{method:body?'POST':'GET',signal:controller.signal,
      credentials:'same-origin',headers:{'X-Game-Account-Mode':gameAccountMode,...(token?{Authorization:'Bearer '+token}:{}),...(body?{'content-type':'application/json'}:{})},
      body:body?JSON.stringify(body):undefined});
    let data;
    try{data=await response.json()}catch{throw new Error('Réponse du serveur illisible. Réessaie dans un instant.')}
    if(!response.ok){
      const err=new Error(data.error||'Connexion interrompue. Réessaie.');
      err.status=response.status;err.retryAfterMs=data.retryAfterMs;
      throw err;
    }
    return data;
  }catch(e){
    if(controller.signal.aborted||e instanceof TypeError)throw new Error('Connexion au jeu interrompue. Vérifie ton réseau et réessaie.');
    throw e;
  }finally{clearTimeout(timeout)}
}
function applyMe(p){me=p;if(window.applyHudGrade)applyHudGrade(p.level||1);if(typeof refreshLureTiers==='function')refreshLureTiers();const kind=$('gameAccountLabel');kind.textContent=gameAccountMode==='guest'?'● Invité':'✓ Participant';kind.dataset.kind=gameAccountMode||'';$('nickname').textContent=me.nickname;$('level').textContent=me.level;$('coins').textContent=me.coins;$('points').textContent=me.points;$('count').textContent=me.catches;$('contestProgress').textContent=me.speciesCount+'/'+SPECIES.length+' espèces · bonus +'+me.contestBonus+' pts';let min=80*(me.level-1)**2,max=80*me.level**2;$('xpLabel').textContent=(me.xp-min)+' / '+(max-min)+' XP';$('xpbar').style.width=Math.min(100,(me.xp-min)/(max-min)*100)+'%';$('wallet').textContent=me.coins;$('action').disabled=starting||(phase!=='walk'&&!manualPhase())||!active;}
function onlineStatus(data){
  const badge=$('online');
  const humans=data?.humanOnline ?? data?.online;
  const live=Number.isInteger(humans);
  const label=live ? humans+' joueur'+(humans>1?'s':'')+' en ligne' : 'Reconnexion…';
  if(badge.textContent!==label)badge.textContent=label;
  badge.dataset.live=String(live);
}
function updateLiveRanks(rows,place){
  if(!Array.isArray(rows))return;
  const top=rows.slice(0,5);
  const list=$('liveRows');list.replaceChildren();
  for(const [index,row] of top.entries()){
    const item=document.createElement('li'),number=document.createElement('b'),name=document.createElement('span'),score=document.createElement('b');
    if(row.id===me?.id)item.className='self';
    number.textContent=index+1;name.textContent=(index===0&&row.points>0?'👑 ':'')+row.nickname+(row.kind==='Invité'?' · Invité':'');if(row.level)name.prepend(gradeChip(row.level),' ');score.textContent=row.points+' pts';
    item.append(number,name,score);list.append(item);
  }
  $('livePlace').textContent=place&&(me?.points>0)?'· Ta place : '+place+(place===1?'er':'e'):'· Pêche pour être classé';
}
