function displayRules(settings){
  const fields=$('ruleFields');
  fields.replaceChildren();
  for(const [heading,rules] of staffGroups){
    const group=document.createElement('fieldset'),legend=document.createElement('legend');
    legend.textContent=heading;group.append(legend);
    for(const [key,title,unit,help] of rules){
      const label=document.createElement('label'),copy=document.createElement('span'),small=document.createElement('small'),select=document.createElement('select');
      copy.textContent=title;small.textContent=help;copy.append(small);select.name=key;select.setAttribute('aria-label',title);
      for(const value of staffRules.choices[key])select.add(new Option(value.toLocaleString('fr-FR')+' '+unit,value,false,value===settings[key]));
      select.onchange=markRuleDraft;label.append(copy,select);group.append(label);
    }
    fields.append(group);
  }
}
