function updateStaffSelection(){
  const n=selectedStaffPlayers.size;
  $('playersSelectedCount').textContent=n+' personnage'+(n>1?'s':'')+' sélectionné'+(n>1?'s':'');
  $('deleteSelectedPlayers').disabled=changingPlayer||n===0;
}
async function loadPlayers(message=''){
  const seq=++playersRequest;
  choosePlayer(null);selectedStaffPlayers.clear();updateStaffSelection();$('managedList').replaceChildren();$('playersMsg').textContent='Chargement…';
  $('prevPlayers').disabled=$('nextPlayers').disabled=true;
  try{
    const data=await api('staff/players?q='+encodeURIComponent(playersSearch)+'&page='+playersPage+'&kind='+playersKind);
    if(seq!==playersRequest)return;
    $('staffPlayerTotals').textContent=data.totals.all+' personnages · '+data.totals.guest+' invités · '+data.totals.participant+' participants';
    for(const row of data.players){
      const item=document.createElement('div');item.className='staffPlayerRow';
      const checkbox=document.createElement('input');checkbox.type='checkbox';checkbox.setAttribute('aria-label','Sélectionner '+row.nickname+' ('+row.kind+')');
      checkbox.onchange=()=>{if(checkbox.checked)selectedStaffPlayers.add(row.public_id);else selectedStaffPlayers.delete(row.public_id);updateStaffSelection()};
      const button=document.createElement('button');button.type='button';
      const title=document.createElement('b');title.textContent=row.nickname;
      const details=document.createElement('small');details.textContent='';details.append(gradeChip(1+Math.floor(Math.sqrt(row.xp/80)),{name:true}),document.createTextNode(' · '+row.catches+' prises · '+(row.seen>data.serverTime-12000?'En ligne':'Hors ligne')));
      button.append(title,details);button.onclick=()=>{if(!changingPlayer)choosePlayer(row)};
      const kind=document.createElement('span');kind.className='staffType'+(row.kind==='Invité'?' guest':'');kind.textContent=row.kind==='Invité'?'Invité':'Inscrit';
      item.append(checkbox,button,kind);$('managedList').append(item);
    }
    $('prevPlayers').disabled=playersPage===0;$('nextPlayers').disabled=!data.more;
    $('playersMsg').textContent=message||(data.players.length?'Choisis un personnage à gérer ou sélectionne-en plusieurs.':'Aucun personnage trouvé avec ce filtre.');
  }catch(e){if(seq===playersRequest)$('playersMsg').textContent=e.message}
}
