$('playerEditor').onsubmit=async e=>{
  e.preventDefault();if(!selectedPlayer||changingPlayer)return;
  const row=selectedPlayer,field=$('editField').value,value=$('editValue').valueAsNumber;
  if(!Number.isInteger(value)||value<0||value>statLimits[field])return;
  changingPlayer=true;
  try{await api('staff/players',{action:'edit',target:row.public_id,field:field==='level'?'xp':field,value:field==='level'?(1+Math.floor(Math.sqrt(row.xp/80))===value?row.xp:80*(value-1)**2):value,previous:field==='level'?row.xp:row[field]});
    await loadPlayers('Modification enregistrée pour '+row.nickname+'.')}
  catch(err){await loadPlayers(err.message)}
  finally{changingPlayer=false}
};
async function resetFishing(all){
  const row=selectedPlayer;
  if(changingPlayer||(!all&&!row))return;
  const target=all?'tous les joueurs':row.nickname+' ('+row.public_id+')';
  const message='Effacer les prises, records et points de '+target+' ? Les lancers en cours seront annulés. Les pièces, l’XP et le matériel seront conservés.';
  if(all){
    if(window.prompt(message+' Saisis TOUS pour confirmer.')!=='TOUS')return;
  }else if(!window.confirm(message))return;
  changingPlayer=true;
  try{
    const payload=all?{scope:'all',confirmation:'TOUS'}:{scope:'player',target:row.public_id,confirmation:row.public_id};
    const result=await api('staff/players',{action:'resetFishing',...payload});
    await loadPlayers(all?'Statistiques de pêche remises à zéro pour '+result.profiles+' profils.':'Statistiques de pêche remises à zéro pour '+row.nickname+'.');
  }catch(err){await loadPlayers(err.message)}
  finally{changingPlayer=false}
}
