async function saveCatch(){if(savingCatch||catchSaved||!castTicket)return;pendingLanding(castTicket);savingCatch=true;$('recast').hidden=true;catchSaved=false;catchDiscardable=false;$('release').disabled=true;$('release').textContent='ENREGISTREMENT…';$('reward').textContent='Validation de ta prise en ligne…';try{const result=await api('land',{ticket:castTicket});pendingLanding(null);const oldLevel=me.level;applyMe(result.me);const f=result.capture;showTrophyComparison(f);session.unshift(f);session=session.slice(0,60);const unique=f.unique;$('fishTitle').textContent=(unique?'✨ UNIQUE · ':(f.trophy?'🏆 TROPHÉE · ':''))+(unique?unique.title:f.name)+' · '+f.size+' mm';$('catch').classList.toggle('trophy-catch',!!f.trophy||!!unique);$('fishInfo').textContent=(unique?unique.zoneName+' · ':'')+f.spot+' · '+f.lure+' · '+f.size+' mm × '+String(f.coefficient).replace('.',',')+' = '+f.points+' pts'+(f.bonusAdded?' · Bonus multi-espèces +'+f.bonusAdded+' pts':'')+(unique?' · Poisson unique très rare':'' );$('reward').textContent='+'+f.coins+' pièces · +'+f.xp+' XP'+(me.level>oldLevel?' · NIVEAU '+me.level+' !':'')+(unique?' · PRIME UNIQUE !':'');const bonus=f.manualBonus||castData?.manualBonus;if(bonus)$('reward').textContent+=' · Bonus Manuel inclus (+25 %) : +'+bonus.coins+' pièces et +'+bonus.xp+' XP';$('release').textContent='RELÂCHER ET CONTINUER';catchSaved=true;lastRanks=0;refreshQuestTracker();$('recast').hidden=false}catch(e){catchDiscardable=e.status===409&&!e.retryAfterMs;if(catchDiscardable)pendingLanding(null);if(e.retryAfterMs){const ticket=castTicket;setTimeout(()=>{if(castTicket===ticket&&phase==='result'&&!catchSaved)saveCatch()},e.retryAfterMs+100)}$('reward').textContent=e.message+(catchDiscardable?'':' Ta prise reste en attente.');$('release').textContent=catchDiscardable?'CONTINUER':'RÉESSAYER L’ENREGISTREMENT'}finally{savingCatch=false;$('release').disabled=false}}
async function animateLanding(name,x,y){
  const art=$('catchArt');
  const svg=art.querySelector?.('svg[aria-label="'+name+'"]');
  if(svg&&typeof Element!=='undefined'&&Element.prototype.animate&&!window.matchMedia('(prefers-reduced-motion: reduce)').matches){
    const sprite=new Image();
    const graphic=svg.cloneNode(true);
    graphic.setAttribute('xmlns','http://www.w3.org/2000/svg');
    sprite.src='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(graphic.outerHTML);
    sprite.alt='';sprite.className='landedSprite';
    sprite.style.left=(w/2+(x-camera.x)*scale)+'px';
    sprite.style.top=(h/2+(y-camera.y)*scale*VT)+'px';
    document.body.append(sprite);
    const style=getComputedStyle(art),dx=parseFloat(style.getPropertyValue('--side'))||0;
    const height=32+Math.abs(parseFloat(style.getPropertyValue('--jump'))||0)*2;
    const tilt=style.getPropertyValue('--twist').trim()||'0deg';
    try{
      const motion=sprite.animate([
        {transform:'translate(-50%,0) scale(.4)',opacity:0},
        {transform:'translate(calc(-50% + '+dx+'px),-'+height+'px) rotate('+tilt+')',opacity:1,offset:.52},
        {transform:'translate(-50%,-16px) scale(.85)',opacity:.9}
      ],{duration:700,easing:'ease-out'});
      await motion.finished;
    }catch{}finally{sprite.remove()}
  }
}
