// Renvoie le SVG de l'espèce, recoloré avec la palette du poisson unique (ou tel quel si pas de palette).
function fishMarkup(species,palette,suffix){
  const src=document.querySelector('#catchArt svg[aria-label="'+species+'"]');
  if(!src)return '';
  let m=src.outerHTML;
  const ids=[...m.matchAll(/ id="([^"]+)"/g)].map(x=>x[1]);
  for(const id of ids)m=m.split('id="'+id+'"').join('id="'+id+suffix+'"').split('#'+id+')').join('#'+id+suffix+')');
  if(palette){
    m=m.replace(/(fill|stop-color|stroke)="(#[0-9a-fA-F]{6})"/g,(all,attr,hex)=>{
      hex=hex.toLowerCase();if(FISH_PROTECTED.has(hex))return all;
      const [h,sat,l]=hexToHsl(hex);
      const nh=palette.h+Math.max(-45,Math.min(45,h-70))*.45;
      const ns=Math.max(0,Math.min(1,palette.s*Math.pow(Math.max(.05,sat)/.35,.6)));
      const nl=Math.max(.06,Math.min(.94,palette.l+(l-.5)*.9));
      return attr+'="'+hslToHex(nh,ns,nl)+'"';
    });
  }
  return m.replace('<svg ','<svg width="100%" height="100%" ');
}
function uniqueFishMarkup(data){return fishMarkup(data.species,paletteForUnique(data),'_u')}
