let celebrateTimer=0;
function celebrateCatch(kind,info){
  const box=$('celebrate');if(!box||!box.showPopover)return;
  clearTimeout(celebrateTimer);
  const accent=kind==='unique'?(info.accent||'#ffe866'):'#ffd24a';
  const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches||document.body.dataset.settingReduceMotion==='true';
  box.replaceChildren();box.dataset.kind=kind;box.style.setProperty('--cel',accent);
  const rays=document.createElement('div');rays.className='cel-rays';
  const flash=document.createElement('div');flash.className='cel-flash';
  const stage=document.createElement('div');stage.className='cel-stage';
  const fishBox=document.createElement('div');fishBox.className='cel-fish';
  const markup=kind==='unique'?uniqueFishMarkup(info):fishMarkup(info.species,null,'_t');
  fishBox.innerHTML=markup;
  const ribbon=document.createElement('div');ribbon.className='cel-ribbon';
  const kicker=document.createElement('small');kicker.textContent=kind==='unique'?'★ POISSON UNIQUE ★':'🏆 TROPHÉE 🏆';
  const name=document.createElement('b');name.textContent=kind==='unique'?info.title:info.species;
  const size=document.createElement('span');size.textContent=info.size+' mm';
  ribbon.append(kicker,name,size);
  stage.append(fishBox,ribbon);
  if(kind==='unique'&&info.reward){
    const rw=document.createElement('div');rw.className='cel-rewards';
    for(const t of ['+'+(info.reward.coins||0)+' 🪙','+'+(info.reward.xp||0)+' XP']){const chip=document.createElement('span');chip.textContent=t;rw.append(chip)}
    stage.append(rw);
  }
  box.append(rays,flash,stage);
  if(!reduce){
    const glyphs=kind==='unique'?['✦','★','✧','🪙','✨']:['★','🪙','✦','🏆'];
    for(let i=0;i<44;i++){
      const p=document.createElement('i');p.className='cel-p';p.textContent=glyphs[i%glyphs.length];
      const ang=Math.random()*Math.PI*2,dist=90+Math.random()*190;
      p.style.setProperty('--dx',Math.round(Math.cos(ang)*dist)+'px');p.style.setProperty('--dy',Math.round(Math.sin(ang)*dist-40)+'px');
      p.style.setProperty('--rot',Math.round((Math.random()-.5)*540)+'deg');p.style.setProperty('--d',(Math.random()*.35).toFixed(2)+'s');p.style.setProperty('--sz',(12+Math.random()*16).toFixed(0)+'px');
      box.append(p);
    }
  }
  try{navigator.vibrate?.(kind==='unique'?[70,40,70,40,160]:[60,40,110])}catch{}
  try{box.hidePopover()}catch{}
  box.showPopover();
  box.onclick=()=>{clearTimeout(celebrateTimer);try{box.hidePopover()}catch{}};
  celebrateTimer=setTimeout(()=>{try{box.hidePopover()}catch{}},kind==='unique'?4200:3400);
}
