  if(notice.showPopover)notice.showPopover();
  const sx=w/2+(event.x-camera.x)*scale,sy=h/2+(event.y-camera.y)*scale*VT;
  if(sx>=0&&sx<=w&&sy>=0&&sy<=h)animateLanding(event.name,event.x,event.y);
