function drySegment(a,b){
  const steps=Math.max(1,Math.ceil(dist(a,b)/2));
  for(let i=1;i<=steps;i++){
    if(!walkable({x:a.x+(b.x-a.x)*i/steps,y:a.y+(b.y-a.y)*i/steps}))return false;
  }
  return true;
}
