function measureTourCue(){
  if(tour)tour.cueBottom=Math.min(h*.67,$('tourCaption').getBoundingClientRect().top-42);
}
function locateTourCue(){
  if(tour.index===4)return;
  let x=w/2+(tour.focus.x-camera.x)*scale,y=h/2+(tour.focus.y-camera.y)*scale*VT;
  if(tour.index===3||tour.index===5){x=w/2;y=tour.cueBottom}
  
  $('tourCue').style.left=Math.max(90,Math.min(w-90,x))+'px';
  $('tourCue').style.top=Math.max(70,Math.min(tour.cueBottom,y))+'px';
}
function advanceTour(dt){
  if(!tour)return;
  tour.elapsed+=dt;tour.walkAngle=null;
  if(tourDestinations[tour.index]){
    if(!tour.arrived)advanceTourWalk(dt);
    const target=tourDestinations[tour.index];
    const lead=Math.min(.5,50/(dist(player,target)||1));
    tour.to.x=player.x+(target.x-player.x)*lead;
    tour.to.y=player.y+(target.y-player.y)*lead+h*.10/tour.to.zoom;
  }
  const u=tour.reduced?1:Math.min(1,tour.elapsed/(tour.index===0?5:2.3)),t=u*u*(3-2*u);
  camera.x=tour.from.x+(tour.to.x-tour.from.x)*t;
  camera.y=tour.from.y+(tour.to.y-tour.from.y)*t;
  const value=tour.from.zoom+(tour.to.zoom-tour.from.zoom)*t;
  scale=value;locateTourCue();
  if(tourScenes[tour.index].practice){
    tour.tension=Math.max(0,Math.min(1,tour.tension+dt*(tour.held?.28:-.13)));
    $('tourGauge').style.left=tour.tension*100+'%';
    const cue=tensionCue(tour.tension,tour.held?.28:-.13),note=cue||'Dans le vert';
    $('tourGauge').dataset.warn=cue?'yes':'';
    if($('tourPracticeNote').textContent!==note)$('tourPracticeNote').textContent=note;
  }
}
function drawTourCast(){
  if(!tour||tour.index!==3||!tour.demoStep)return;
  const origin=player,water=tourWater,cycle=tour.reduced?1.5:Math.min(2.5,tour.elapsed-tour.castStart);
  const progress=Math.min(1,cycle/.95);
  const t=fishingMode==='auto'&&cycle>.95?Math.max(0,1-(cycle-.95)/1.55):tour.demoStep===1?progress:tour.demoStep===2?1-progress*.6:.4;
  const sx=w/2+(origin.x-camera.x)*scale,sy=h/2+(origin.y-camera.y)*scale*VT;
  const ex=w/2+(water.x-camera.x)*scale,ey=h/2+(water.y-camera.y)*scale*VT;
  const x=sx+(ex-sx)*t,y=sy+(ey-sy)*t-Math.sin(Math.PI*t)*32;
  ctx.save();ctx.setTransform(canvas.width/w,0,0,canvas.height/h,0,0);
  ctx.beginPath();ctx.moveTo(sx,sy);ctx.quadraticCurveTo((sx+x)/2,(sy+y)/2-14,x,y);
  ctx.strokeStyle='#fff5cd';ctx.lineWidth=2;ctx.stroke();
  if(t===1){
    const radius=5+Math.max(0,cycle-.95)*10;
    ctx.beginPath();ctx.ellipse(x,y,radius,radius*.48,0,0,Math.PI*2);
    ctx.strokeStyle='#fff8';ctx.stroke();
  }
  ctx.beginPath();ctx.arc(x,y,4,0,Math.PI*2);ctx.fillStyle='#ffd363';ctx.fill();ctx.restore();
}
