let questRead=0,bookRead=0,claimBusy=false;
let questResetTimer;
function scheduleQuestReset(data){
  clearTimeout(questResetTimer);
  questResetTimer=setTimeout(refreshQuestTracker,Math.max(100,data.resetAt-data.serverTime+100));
}
function showQuestTracker(list){
  for(const kind of ['quest','challenge']){
    const values=list.filter(q=>kind==='challenge'?q.challenge:!q.challenge);
    const unfinished=values.filter(q=>!q.claimed);
    const claimable=unfinished.filter(q=>q.progress>=q.target);
    const button=$(kind==='challenge'?'challengeTracker':'questTracker');
    button.hidden=false;
    button.dataset.ready=String(claimable.length>0);
    const count=$(kind==='challenge'?'challengeCount':'questCount');
    count.textContent=unfinished.length;
    const dot=$(kind==='challenge'?'challengeDot':'questDot');
    dot.hidden=unfinished.length===0;
    button.title=unfinished.length?(claimable.length?claimable.length+' récompense(s) à récupérer · ':'')+unfinished.length+' '+(kind==='challenge'?'défi(s)':'quête(s)')+' restant(s)':'Tout terminé !';
    button.setAttribute('aria-label',button.title);
  }
}
async function refreshQuestTracker(){
  const request=++questRead;
  try{const data=await api('quests');if(request===questRead){if($('questBook').open){++bookRead;renderQuests(data);$('questStatus').textContent=objectiveKind==='challenge'?'6 défis à accomplir chaque jour.':'Les quêtes du jour se renouvellent à minuit. Les objectifs de carrière se cumulent.'}else{scheduleQuestReset(data);showQuestTracker(data.quests)}}}
  catch{if(request===questRead){clearTimeout(questResetTimer);questResetTimer=setTimeout(refreshQuestTracker,30000)}}
}
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&me)refreshQuestTracker()});
function renderQuests(data){
  const {quests:list,day}=data;
  scheduleQuestReset(data);
  ++questRead;showQuestTracker(list);
  $('questList').replaceChildren();
  let group='';
  const next=Object.values(PERKS).filter(p=>p.level>me.level).sort((a,b)=>a.level-b.level)[0];
  if(next&&objectiveKind!=='challenge'){const note=document.createElement('p');note.textContent='Prochain déblocage au niveau '+next.level+' : '+next.title+' · '+next.cost+' pièces.';$('questList').append(note)}
  for(const q of list.filter(q=>objectiveKind==='challenge'?q.challenge:!q.challenge)){
    const heading=q.challenge?'Défis du jour':q.career?'Objectifs de carrière':'Quêtes du jour';
    if(group!==heading){const h=document.createElement('h3');h.textContent=heading;$('questList').append(h);group=heading}
    const row=document.createElement('article'),title=document.createElement('strong'),goal=document.createElement('p'),reward=document.createElement('p');
    title.textContent=q.title;goal.textContent=q.goal+' · '+q.progress+'/'+q.target;
    reward.textContent=q.coins+' pièces · '+q.xp+' XP'+(q.claimed?' · Récupérées':'');
    const progress=document.createElement('progress');progress.max=q.target;progress.value=q.progress;progress.setAttribute('aria-label',q.title);
    row.dataset.kind=q.challenge?'challenge':'quest';row.dataset.ready=String(!q.claimed&&q.progress===q.target);
    row.append(title,goal,progress,reward);
    if(!q.claimed&&q.progress===q.target){
      const btn=document.createElement('button');btn.textContent='Récupérer';row.append(btn);
      btn.onclick=async()=>{
        if(claimBusy)return;claimBusy=true;++bookRead;btn.disabled=true;
        try{const data=await api('quests',{quest:q.key,day});applyMe(data.me);++bookRead;renderQuests(data);$('questStatus').textContent='Récompense récupérée · '+q.title}
        catch(e){$('questStatus').textContent=e.message;btn.disabled=false;if(e.status===409)refreshQuestTracker()}
        finally{claimBusy=false}
      };
    }
    $('questList').append(row);
  }
}
