let screenLock=null,screenRequest=null,screenRetryAt=0,pageHidden=false;
function releaseGameScreen(){
  screenRequest=null;
  screenRetryAt=0;
  const lock=screenLock;
  screenLock=null;
  if(lock&&!lock.released)lock.release().catch(()=>{});
}
async function keepGameScreenAwake(){
  if(!active||document.hidden||pageHidden||!navigator.wakeLock||screenLock||screenRequest||Date.now()<screenRetryAt)return;
  const request={};
  screenRequest=request;
  try{
    const lock=await navigator.wakeLock.request('screen');
    if(screenRequest!==request||!active||document.hidden||pageHidden){await lock.release();return}
    screenLock=lock;
    lock.addEventListener('release',()=>{
      if(screenLock===lock)screenLock=null;
    },{once:true});
  }catch{
    if(screenRequest===request)screenRetryAt=Date.now()+10000;
  }finally{if(screenRequest===request)screenRequest=null}
}
document.addEventListener('visibilitychange',()=>{
  if(document.hidden)releaseGameScreen();else keepGameScreenAwake();
});
addEventListener('pagehide',()=>{pageHidden=true;releaseGameScreen()});
addEventListener('pageshow',()=>{pageHidden=false;keepGameScreenAwake()});
