async function board(){const request=++boardRequest,mode=boardMode;$('boardFilters').hidden=mode!=='records';$('boardNote').textContent=mode==='records'?'Longueur décroissante en mm, toutes les espèces confondues ou filtrées. À égalité : première capture. Les prises du jeu sont enregistrées en ligne.':'Brochet et sandre ×1,5 · Perche, black-bass et chevesne ×1 · Silure ×0,5. Bonus 3–4 espèces +300 ; 5–6 espèces +500. À égalité : nombre de prises.';try{const data=await api(mode==='records'?'records?species='+encodeURIComponent(recordSpecies)+'&trophies='+(recordTrophies?'1':'0'):'board');if(request!==boardRequest)return;if(mode==='points'){boardRank=data.rank;leaderId=data.leaderId||null;}$('myRank').textContent=mode==='records'?(data.personalBest?'Ton record : '+data.personalBest+' mm':'Pas encore de prise pour ce filtre'):'Ta place : '+data.rank;$('ranks').replaceChildren();if(!data.rows.length){const p=document.createElement('p');p.textContent='Aucune prise pour ce filtre. À toi d’ouvrir le classement !';$('ranks').append(p)}data.rows.forEach((p,i)=>{let row=document.createElement('div');row.className='boardrow'+(p.id===me?.id?' me':'');let rank=document.createElement('b'),text=document.createElement('div'),name=document.createElement('b'),small=document.createElement('small'),pts=document.createElement('b');rank.textContent=i+1;name.textContent=(mode==='points'&&p.id===leaderId?'👑 ':'')+p.nickname+(p.kind==='Invité'?' · Invité':'');small.textContent=mode==='records'?(p.trophy?'🏆 Trophée · ':'')+p.name+' · '+p.spot:'Niveau '+p.level+' · '+p.catches+' prise(s)';if(mode==='points'){small.textContent='';small.append(gradeChip(p.level||1,{name:true}),document.createTextNode(' · '+p.catches+' prise(s)'))}pts.textContent=mode==='records'?p.size+' mm':p.points+' pts';text.append(name,small);row.append(rank,text,pts);$('ranks').append(row)})}catch(e){if(request===boardRequest)$('myRank').textContent=e.message}}
$('boardBtn').onclick=()=>{openDialog('board');board()};$('pointsTab').onclick=()=>setBoardMode('points');$('recordsTab').onclick=()=>setBoardMode('records');function setBoardMode(mode){boardMode=mode;$('pointsTab').setAttribute('aria-selected',String(mode==='points'));$('recordsTab').setAttribute('aria-selected',String(mode==='records'));board()}
