  for(const r of scene.ripples)r.t+=dt;scene.ripples=scene.ripples.filter(r=>r.t<r.max);
  for(const d of scene.drops){d.vy+=520*dt;d.x+=d.vx*dt;d.y+=d.vy*dt;d.life-=dt}scene.drops=scene.drops.filter(d=>d.life>0);
