  if(sceneBgKey!==key||!sceneBg){sceneBgKey=key;sceneBg=document.createElement('canvas');sceneBg.width=Math.ceil(R.w);sceneBg.height=Math.ceil(R.h);const g2=sceneBg.getContext('2d'),g=g2.createLinearGradient(0,0,0,R.h);g.addColorStop(0,'#08303f');g.addColorStop(.5,'#10667a');g.addColorStop(1,'#3fb0ae');g2.fillStyle=g;g2.fillRect(0,0,R.w,R.h);const vg=g2.createRadialGradient(R.w/2,R.h*.45,R.w*.25,R.w/2,R.h*.5,R.w*.85);vg.addColorStop(0,'rgba(0,0,0,0)');vg.addColorStop(1,'rgba(2,20,28,.5)');g2.fillStyle=vg;g2.fillRect(0,0,R.w,R.h)}
