  // caustiques
  ctx.lineWidth=11;ctx.lineCap='round';
  for(let i=0;i<7;i++){ctx.strokeStyle='rgba(215,255,248,'+(.045+.035*Math.sin(t*1.3+i))+')';ctx.beginPath();for(let x=0;x<=R.w;x+=34){const y=R.y+R.h*(i/6)+Math.sin(x*.045+t*1.4+i*1.7)*10+Math.sin(x*.02-t*.9)*8;x?ctx.lineTo(R.x+x,y):ctx.moveTo(R.x+x,y)}ctx.stroke()}
