function marketNode(tag,text,cls){const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n}
function lureSpecialtyText(i){return ['touches plus rapides','pièces en plus','poissons plus grands','précision sur '+LURES[i].target.toLowerCase(),'chance de trophée','expérience en plus'][i]}
function lureBonusText(i,tier){
  const b=lureBonus(i,tier),parts=[];
  if(tier===0)return 'Leurre de base';
  if(b.size)parts.push('+'+Math.round(b.size*100)+' % de taille');
  parts.push('+'+Math.round((b.prec-1)*100)+' % de chances de '+LURES[i].target.toLowerCase());
  parts.push('touche '+Math.round((1-b.bite)*100)+' % plus rapide');
  if(b.trophy)parts.push('+'+String(Math.round(b.trophy*1000)/10).replace('.',',')+' % de trophée');
  if(b.coins)parts.push('+'+Math.round(b.coins*100)+' % de pièces');
  if(b.xp)parts.push('+'+Math.round(b.xp*100)+' % d’XP');
  return parts.join(' · ');
}
function catalogue(){if(!me||!currentVenue)return[];const v=currentVenue.id;
 const permanent=Object.entries(PERKS).filter(([,perk])=>perk.venue===v).map(([id,perk])=>{
   const owned=!!me.perks?.includes(id),locked=!owned&&me.level<(perk.level||1);
   const desc=id==='trophy'&&trophyOdds?'Double tes chances : '+Math.round(trophyOdds.outside*200)+' % hors zone et '+Math.round(trophyOdds.zone*200)+' % en zone par poisson.':perk.desc;
   return {...perk,desc,id,kind:perk.level?'Bonus permanent · Niveau '+perk.level:'Bonus permanent',before:owned?'Activé':'Disponible',after:desc,locked,disabled:owned||locked,status:owned?'Acquis':locked?'Niveau '+perk.level+' requis':'Disponible',action:'DÉBLOQUER'};
 });
 const upgrades={rod:['Canne de précision','Des touches plus fréquentes et des combats plus rapides (rendement réduit après le niveau 5).','🎣',n=>'Moins de lancers sans touche · combat +'+Math.round(effLevel(n)*8)+' %'],line:['Fil renforcé','Raccourcit les départs du poisson (rendement réduit après le niveau 5).','🧵',n=>'Durée des départs −'+Math.round(effLevel(n)*10)+' %'],boots:['Chaussures de berge','Explore plus vite toute la Sèvre (rendement réduit après le niveau 5).','🥾',n=>'Vitesse de marche +'+Math.round(effLevel(n)*8)+' %']};
 const lureOffers=LURES.map((lure,i)=>{
   const tier=me.lures?.[i]||0,next=LURE_TIERS[tier+1],locked=!!next&&me.level<next.level;
   return {id:'lure'+i,lureIndex:i,title:lure.name+' · '+LURE_TIERS[tier].name+(next?' → '+next.name:''),desc:'Cible : '+lure.target+'. Point fort : '+lureSpecialtyText(i)+'.',n:tier,level:next?.level,cost:next?next.cost:0,kind:'Qualité du leurre',before:lureBonusText(i,tier),after:next?lureBonusText(i,tier+1):lureBonusText(i,tier),locked,disabled:!next||locked,status:!next?'Qualité maximale':locked?'Niveau '+next.level+' requis':'Palier '+(tier+1)+' / '+(LURE_TIERS.length-1),action:'AMÉLIORER'};
 });
 const upgradeOffer=id=>{const [title,desc,icon,stat]=upgrades[id],n=me[id]||0,tier=UPGRADE_TIERS[n],locked=!!tier&&me.level<tier.level;return{id,title,desc,icon,n,level:tier?.level,cost:tier?tier.cost:0,kind:'Amélioration permanente',before:stat(n),after:stat(Math.min(UPGRADE_TIERS.length,n+1)),locked,disabled:!tier||locked,status:!tier?'Niveau maximum':locked?'Niveau '+tier.level+' requis':'Niveau '+n+' / '+UPGRADE_TIERS.length,action:'AMÉLIORER'}};
 if(v==='tackle'||v==='atelier')return(v==='tackle'?['rod','line'].map(upgradeOffer).concat(lureOffers):['boots'].map(upgradeOffer)).concat(permanent);
 const timed=id=>{const coffee=id==='coffee',until=me[coffee?'coffeeUntil':'guideUntil']||0,enabled=until>Date.now();return{id,title:coffee?'Le café du pêcheur':'Les conseils du guide',desc:coffee?'Gagne davantage d’expérience sur chaque poisson.':'Gagne davantage de pièces sur chaque poisson.',icon:coffee?'☕':'🐟',cost:Math.round((coffee?25:35)*coinScale(me.level)),kind:'Bonus · 15 minutes',before:enabled?'Bonus déjà actif':'Aucun bonus',after:coffee?'+25 % d’XP par prise.':'+20 % de pièces par prise.',disabled:enabled,status:enabled?'Actif · '+Math.ceil((until-Date.now())/60000)+' min restantes':'Activé dès l’achat',action:'ACTIVER'};};
 if(v==='cafe')return[timed('coffee'),...permanent];return[timed('guide'),...permanent,...Object.entries({olive:['Tenue olive',0],blue:['Tenue rivière',180],red:['Tenue brique',300],gold:['Tenue dorée',600]}).map(([id,[title,price]])=>{const owned=me.skins.includes(id),equipped=me.skin===id;return{id,title,desc:'Personnalise ton pêcheur sur le parcours et pour les autres joueurs.',icon:'tenue',cost:owned?0:price,kind:'Tenue · apparence',before:'Tenue actuelle',after:title,disabled:equipped,status:equipped?'Équipée':owned?'Dans ton vestiaire':'À débloquer',action:owned?'ÉQUIPER':'ACHETER ET ÉQUIPER'}})]}
