function storeItem(offer,near){
  const row=marketNode('article',undefined,'storeItem');
  if(offer.icon==='tenue'){
    const preview=document.createElement('canvas');preview.width=80;preview.height=60;
    const pen=preview.getContext('2d');pen.translate(26,34);pen.scale(1.3,1.3);paintAngler(pen,offer.id,0,2);row.append(preview);
  }
  const timed=offer.id==='coffee'||offer.id==='guide',skin=offer.icon==='tenue';
  const category=skin?'skin':timed?'timed':offer.n!==undefined?'upgrade':'permanent';
  const labels={timed:'◷  15 minutes',permanent:'◆  Permanent',upgrade:'↑  Amélioration permanente',skin:'Tenue'};
  row.dataset.category=category;
  if(offer.lureIndex!==undefined){const ico=marketNode('span',undefined,'storeIcon lureIcon');ico.innerHTML=lureIconSvg(offer.lureIndex);row.prepend(ico)}else if(!skin&&offer.icon)row.prepend(marketNode('span',offer.icon==='〰'?'🧵':offer.icon,'storeIcon'));
  row.append(marketNode('small',labels[category],'storeBadge'),marketNode('h3',offer.title));
  const effect=offer.n!==undefined?((offer.disabled&&!offer.locked)?offer.before:(offer.lureIndex!==undefined?'Palier suivant : ':'Niveau '+(offer.n+1)+' · ')+offer.after)
    :offer.icon==='tenue'?'Tenue visible par les autres joueurs.':offer.after;
  const description=marketNode('p',undefined,'offerBenefit');
  if(!skin)description.append(marketNode('strong',storeEffects[offer.id]+' · '));
  description.append(marketNode('span',skin?'Change l’apparence du pêcheur.':effect));
  row.append(description);
  const actions=marketNode('div',undefined,'storeActions');
  const missing=Math.max(0,offer.cost-me.coins);
  const state=offer.locked?'Niveau '+offer.level+' requis':offer.disabled?offer.status:missing?'Il manque '+missing+' pièces':!near?'Disponible sur place':'';
  if(state)actions.append(marketNode('small',state));
  if(offer.disabled||missing||!near){
    if(offer.cost&&(!offer.disabled||offer.locked))actions.append(marketNode('b',offer.cost+' pièces'));
  }else{
    const verb=offer.icon==='tenue'&&!offer.cost?'Équiper':offer.n!==undefined?'Améliorer':timed?'Activer':'Acheter';
    const button=marketNode('button',verb+(offer.cost?' · '+offer.cost+' pièces':''));
    button.disabled=marketBusy||marketRefreshing||phase!=='walk'||starting;button.onclick=()=>buy(offer.id);
    actions.append(button);
  }
  row.append(actions);return row;
}
const storeTabIcons={tackle:'🎣',cafe:'☕',atelier:'🥾',club:'🐟'},storeTabNames={tackle:'Pêche',cafe:'Café',atelier:'Atelier',club:'AAPPMA'};
function renderStoreTabs(){
  const box=$('storeTabs');if(!box)return;
  if(!box.childElementCount){
    for(const option of $('storeSelect').options){
      const tab=document.createElement('button');tab.type='button';tab.role='tab';tab.dataset.venue=option.value;
      tab.append(marketNode('span',storeTabIcons[option.value]||'🛒','tabIcon'),marketNode('span',storeTabNames[option.value]||option.textContent));
      tab.onclick=()=>{if(marketBusy||$('storeSelect').value===option.value)return;$('storeSelect').value=option.value;$('storeSelect').onchange()};
      box.append(tab);
    }
  }
  for(const tab of box.children){tab.setAttribute('aria-selected',String(tab.dataset.venue===currentVenue?.id));tab.disabled=marketBusy}
}
shop=function(){
  if(!me||!currentVenue)return;
  const v=currentVenue,near=marketNear(),select=$('storeSelect');
  select.value=v.id;select.disabled=marketBusy;renderStoreTabs();
  $('shopLogo').hidden=v.id!=='club';$('shopTitle').textContent=v.name;$('wallet').textContent=me.coins;$('shopTip').hidden=me.coins>0;
  $('marketGo').hidden=near;$('marketGo').textContent='Rejoindre cette boutique pour acheter';
  $('marketGo').disabled=marketBusy||phase!=='walk'||starting;
  const offers=catalogue(),locked=offers.filter(o=>o.locked).sort((a,b)=>a.level-b.level);
  $('upgrades').replaceChildren(...offers.filter(o=>!o.locked).map(o=>storeItem(o,near)));
  $('storeLater').hidden=!locked.length;
  $('storeLaterTitle').textContent='À débloquer ('+locked.length+')';
  $('storeLocked').replaceChildren(...locked.map(o=>storeItem(o,near)));
};
buy=async function(id){if(marketBusy||marketRefreshing||!marketNear()||phase!=='walk'||starting)return;const offer=catalogue().find(x=>x.id===id);if(!offer||offer.disabled||offer.cost>me.coins)return;marketBusy=true;$('shopError').textContent='';shop();try{await api('sync',{x:player.x,y:player.y,phase,withRanks:false,...(pendingSafeTravel?{travel:pendingSafeTravel}:{})});pendingSafeTravel=null;const data=await api('buy',{item:id,expectedLevel:offer.n,venue:currentVenue.id,x:player.x,y:player.y});applyMe(data.me);$('shopError').textContent=data.message;updateVillage()}catch(e){$('shopError').textContent=e.message}finally{marketBusy=false;shop()}};
setInterval(()=>{if($('shop').open&&!marketBusy&&!marketRefreshing)shop()},10000);

