 g.beginPath();g.roundRect(-width/2,-15,width,30,8);g.fill();g.stroke();
 if(clubLogo.complete&&clubLogo.naturalWidth)g.drawImage(clubLogo,-width/2+2,-12,24,24);
 else{g.fillStyle='#fff';g.font='bold 11px system-ui';g.fillText('A',-width/2+10,4)}
 if(near){g.textAlign='left';g.font='bold 10px system-ui';g.fillStyle='#ecd89e';g.fillText('AAPPMA',-50,-2);
 g.font='bold 12px system-ui';g.fillStyle='#fff7df';g.fillText('Le Gardon Mortagnais',-50,11,125)}
