const storefrontPalette={
  tackle:{roof:'#25758a',dark:'#154858',light:'#83d7dc'},
  cafe:{roof:'#ab5342',dark:'#66372c',light:'#ffe3ad'},
  atelier:{roof:'#ad752b',dark:'#654e34',light:'#f8ce78'},
  club:{roof:'#397058',dark:'#193f33',light:'#cadab4'}
};
function drawStorefront(g,v){
  const {roof,dark,light}=storefrontPalette[v.id];
  g.save();g.translate(v.x,v.y);g.scale(v.w/60,v.h/44);
  function shape(points,fill){
    g.fillStyle=fill;g.beginPath();points.forEach(([x,y],i)=>i?g.lineTo(x,y):g.moveTo(x,y));g.closePath();g.fill();
  }
  g.fillStyle='#314b3438';g.fillRect(-27,-18,60,55);
  g.fillStyle='#f1dfb6';g.fillRect(-29,-20,58,51);
  g.fillStyle=dark;g.fillRect(-27,12,54,18);
  g.fillStyle='#b6dfd7';g.fillRect(-24,16,17,10);g.fillRect(10,16,14,10);
  g.fillStyle='#463e33';g.fillRect(-4,15,10,16);
  if(v.id==='atelier'){
    shape([[-32,12],[-32,-20],[-11,-31],[-11,-20],[10,-31],[10,-20],[31,-31],[31,12]],roof);
    for(const x of [-31,-10,11])shape([[x,-19],[x+18,-28],[x+18,-23],[x,-14]],light);
    g.fillStyle='#4c5047';g.fillRect(-25,16,25,14);
    for(let y=17;y<30;y+=4){g.fillStyle='#c9bf9d';g.fillRect(-24,y,23,1)}
  }else{
    shape([[-33,-20],[-15,-31],[20,-30],[32,-19],[32,12],[-33,12]],roof);
    shape([[-33,-20],[-15,-31],[20,-30],[32,-19]],light);
    if(v.id==='cafe'){
      for(let i=0;i<8;i++){
        const x=-32+i*8;
        shape([[x,5],[x+8,5],[x+9,17],[x-1,17]],i%2?'#fff0ce':'#cb604c');
      }
      for(const x of [-20,18]){
        g.fillStyle=dark;g.fillRect(x-1,28,2,6);
        g.fillStyle='#dfc693';g.beginPath();g.ellipse(x,29,5,3,0,0,7);g.fill();
      }
    }else if(v.id==='tackle'){
      // Fish-shaped shop sign, readable even when zoomed out.
      g.fillStyle='#e6f6d7';g.beginPath();g.ellipse(0,-4,13,5,-.1,0,7);g.fill();
      shape([[-10,-4],[-19,-10],[-18,2]],'#e6f6d7');g.fillStyle=dark;g.fillRect(7,-6,2,2);
      g.fillStyle=light;g.fillRect(-32,10,64,4);
    }else{
      g.fillStyle=dark;g.fillRect(-12,-21,24,25);
      if(clubLogo.complete&&clubLogo.naturalWidth)g.drawImage(clubLogo,-12,-21,24,24);
      g.fillStyle=light;g.fillRect(-32,10,64,3);
    }
  }
  g.fillStyle='#e7d2a2';g.fillRect(-6,30,14,3);g.restore();
}
const venueNames={tackle:'Magasin de pêche',cafe:'Café-PMU',atelier:'Atelier',club:'AAPPMA'};
function drawMarkerPin(g,x,y,pal,emoji,label,t,seed,logo){
  const bob=Math.sin(t*2.3+seed)*2.2;
  g.save();g.translate(x,y);g.scale(1/scale,1/(scale*VT));g.translate(0,bob);
  // ombre + corps du repère (goutte)
  g.fillStyle='#00000040';g.beginPath();g.ellipse(0,3,11,4,0,0,7);g.fill();
  const R=19;g.beginPath();g.moveTo(0,0);g.lineTo(-9,-R*.9);g.arc(0,-R-8,R,Math.PI*.83,Math.PI*.17,false);g.lineTo(0,0);g.closePath();
  const gr=g.createLinearGradient(0,-R*2-8,0,0);gr.addColorStop(0,pal.light);gr.addColorStop(1,pal.roof);
  g.fillStyle=gr;g.fill();g.lineWidth=3;g.strokeStyle='#fffbe6';g.stroke();
  g.beginPath();g.arc(0,-R-8,R-5,0,Math.PI*2);g.fillStyle=pal.dark;g.fill();
  if(logo&&clubLogo.complete&&clubLogo.naturalWidth){g.save();g.beginPath();g.arc(0,-R-8,R-6,0,Math.PI*2);g.clip();g.drawImage(clubLogo,-(R-6),-R-8-(R-6),(R-6)*2,(R-6)*2);g.restore()}
  else{g.font='20px system-ui';g.textAlign='center';g.textBaseline='middle';g.fillStyle='#fff';g.fillText(emoji,0,-R-7)}
  if(label&&scale>=.3){
    g.font='800 11px system-ui';const tw=g.measureText(label).width+14,ly=-R*2-26;
    g.beginPath();g.roundRect(-tw/2,ly,tw,19,9.5);g.fillStyle='#0b2f2af0';g.fill();g.lineWidth=1.6;g.strokeStyle=pal.light;g.stroke();
    g.fillStyle='#fff6d2';g.textAlign='center';g.textBaseline='middle';g.fillText(label,0,ly+10);
  }
  g.restore();
}
function drawVillage(){
 const g=ctx,t=performance.now()/1000;g.save();
 for(const v of VILLAGE){
  if(!visible(v,260))continue;
  const pal=storefrontPalette[v.id],near=venueAt(player)?.id===v.id,pulse=.5+.5*Math.sin(t*2.4+v.x);
  // 1. Place dallée de la couleur du commerce + halo pulsant : repérable de loin.
  g.save();g.translate(v.x+(v.doorX-v.x)*.5,v.y+v.h*.45);
  g.fillStyle=pal.light+(near?'70':'42');g.beginPath();g.ellipse(0,0,v.w*1.1+pulse*2.5,v.h*1.0+pulse*2,0,0,7);g.fill();
  g.strokeStyle=pal.light;g.globalAlpha=.5+.35*pulse;g.lineWidth=Math.max(1.4,1.6/scale*.5);g.setLineDash([5,4]);g.stroke();g.setLineDash([]);g.globalAlpha=1;
  g.fillStyle='#f0e4c6';g.strokeStyle='#b9a77c';g.lineWidth=1.2;g.beginPath();g.roundRect(-v.w*.75,-v.h*.55,v.w*1.5,v.h*1.25,5);g.fill();g.stroke();
  g.restore();
  // 2. Seuil + bâtiment agrandi (autour du bas de façade pour garder la porte au même endroit).
  g.strokeStyle='#c6bda2';g.lineWidth=mapUnit(13);g.beginPath();g.moveTo(v.doorX,v.y+v.h/2+mapUnit(10));g.lineTo(v.doorX,v.doorY+mapUnit(7));g.stroke();
  if(VT>=.99){g.save();const pivotY=v.y+v.h*.75,k=1.6;g.translate(v.x,pivotY);g.scale(k,k);g.translate(-v.x,-pivotY);drawStorefront(g,v);g.restore()}
  g.strokeStyle=near?'#e9efb0':'#ffd86b';g.lineWidth=near?2.8:2;g.beginPath();g.ellipse(v.doorX,v.doorY,mapUnit(13),mapUnit(8),0,0,7);g.stroke();
 }
 // 3. Grands repères (goutte + icône + nom), toujours visibles ; regroupés si trop proches.
 venuePins.length=0;
 const crowded=VILLAGE.some((v,i)=>VILLAGE.slice(i+1).some(other=>dist(v,other)*scale<34));
 const pins=crowded?[{x:VILLAGE.reduce((n,v)=>n+v.x,0)/VILLAGE.length,y:Math.min(...VILLAGE.map(v=>v.y))-mapUnit(6),group:true}]:VILLAGE.map(v=>({x:v.x,y:v.y-v.h*.62-(VT<1?9/VT:0)-10/(scale*VT),venue:v}));
 pins.forEach((pin,i)=>{
   if(!visible(pin,60))return;
   venuePins.push({...pin,y:pin.y-27/(scale*VT)});   // zone de toucher = centre du repère
   const pal=pin.group?{light:'#ffd27c',dark:'#503a20',roof:'#8a6a2f'}:storefrontPalette[pin.venue.id];
   deferTop(()=>drawMarkerPin(g,pin.x,pin.y,pal,pin.group?'🏪':venueIcons[pin.venue.id],pin.group?'Boutiques':venueNames[pin.venue.id],t,i*1.7,pin.venue?.id==='club'));
 });
 if(navigationTarget){const v=navigationTarget;g.strokeStyle='#f1d26b';g.lineWidth=3/scale;g.setLineDash([9/scale,7/scale]);g.beginPath();g.moveTo(player.x,player.y);g.lineTo(v.doorX,v.doorY);g.stroke();g.setLineDash([]);}
 g.restore();
}

const netMessage=document.createElement('p');netMessage.id='netmessage';netMessage.className='statusnote';netMessage.textContent='Choisis un accès pour commencer.';$('start').before(netMessage);$('start').disabled=true;$('welcome').showModal();loop(performance.now());
const accountModeKey='sf-game-account-mode-v164';
function showAccountChoice(message='Choisis ton mode de jeu.'){
  $('accountEntry').hidden=false;$('characterEntry').hidden=true;$('start').hidden=true;
  $('guideStart').hidden=true;$('netmessage').textContent=message;
}
async function selectGameMode(mode){
  if(!['guest','participant'].includes(mode))return;
  gameAccountMode=mode;
  $('accountEntry').hidden=true;$('characterEntry').hidden=true;$('start').hidden=true;
  $('netmessage').textContent='Recherche de ton personnage…';
  try{
    if(mode==='participant'&&!await window.participantToken()){
      gameAccountMode=null;
      showAccountChoice('Connecte-toi au site du concours, puis reviens ici pour choisir Compte du concours.');
      return;
    }
    const entry=await api('character');
    try{sessionStorage.setItem(accountModeKey,mode)}catch{}
    if(entry.exists){
      $('guideStart').hidden=false;$('start').hidden=false;
      await init();
      return;
    }
    $('characterTitle').textContent=entry.deleted?'Créer un nouveau personnage':'Créer ton pêcheur';
    $('characterNote').textContent=entry.deleted?'Ton ancien personnage a été supprimé définitivement. Nouveau départ au niveau 1 : aucun ancien bonus, score ou poisson ne sera récupéré.':'Choisis un pseudo : tu commenceras niveau 1, sans inscription au concours.';
    $('characterEntry').hidden=false;
    $('netmessage').textContent=mode==='guest'?'Mode invité : progression liée à ce navigateur.':'Mode participant : progression liée à ton compte.';
  }catch(e){
    gameAccountMode=null;
    try{sessionStorage.removeItem(accountModeKey)}catch{}
    showAccountChoice(e.message);
  }
}
$('playParticipant').onclick=()=>selectGameMode('participant');
$('playGuest').onclick=()=>selectGameMode('guest');
$('backAccountChoice').onclick=()=>{gameAccountMode=null;try{sessionStorage.removeItem(accountModeKey)}catch{}showAccountChoice()};
$('createCharacter').onclick=async()=>{
 const button=$('createCharacter');button.disabled=true;
 try{
  await api('character',{action:'create',nickname:$('newCharacterName').value});
  $('characterEntry').hidden=true;$('guideStart').hidden=false;$('start').hidden=false;
  if(!await init())$('characterEntry').hidden=false;
 }catch(e){$('netmessage').textContent=e.message}
 finally{button.disabled=false}
};
$('newCharacterName').addEventListener('keydown',e=>{if(e.key==='Enter'){$('createCharacter').click();e.preventDefault()}});
$('switchGameAccount').onclick=()=>{try{sessionStorage.removeItem(accountModeKey)}catch{}location.reload()};
// Suppression guidée dans les paramètres, sans window.prompt (peu fiable sur mobile/PWA).
const deletePanel=$('deleteCharacterConfirm');
const deleteInput=$('deleteCharacterText');
const deleteConfirm=$('confirmDeleteCharacter');
const deleteNotice=$('deleteCharacterMessage');
function closeCharacterDeletion(){
  deletePanel.hidden=true;deleteInput.value='';deleteConfirm.disabled=true;
  $('deleteMyCharacter').disabled=false;
}
$('deleteMyCharacter').onclick=()=>{
  if(!me){deleteNotice.textContent='Sélectionne un personnage avant de le supprimer.';return}
  deleteNotice.textContent='';deletePanel.hidden=false;
  deleteInput.value='';deleteConfirm.disabled=true;
  deletePanel.scrollIntoView({block:'nearest',behavior:'smooth'});
  deleteInput.focus({preventScroll:true});
};
$('cancelDeleteCharacter').onclick=()=>{closeCharacterDeletion();deleteNotice.textContent='Suppression annulée.'};
deleteInput.addEventListener('input',()=>{deleteConfirm.disabled=deleteInput.value.trim()!=='SUPPRIMER'});
deleteInput.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();if(deleteInput.value.trim()==='SUPPRIMER'&&!deleteConfirm.disabled)deleteConfirm.click()}});
deleteConfirm.onclick=async()=>{
 if(!me||deleteInput.value.trim()!=='SUPPRIMER')return;
 const currentId=me.id;const button=deleteConfirm;
 button.disabled=true;$('deleteMyCharacter').disabled=true;
 deleteNotice.textContent='Suppression en cours…';
 try{
  const result=await api('character',{action:'delete',confirmation:'SUPPRIMER',publicId:currentId});
  if(!result.deleted)throw new Error('Le serveur n’a pas confirmé la suppression.');
  // Conserve le choix Invité/Participant mais redémarre complètement la partie.
  deleteNotice.textContent='Personnage supprimé. Retour à la création du personnage…';
  active=false;resetInput();releaseGameScreen();
  location.reload();
 }catch(e){
  deleteNotice.textContent='Suppression impossible : '+e.message+' Réessaie ou ouvre ton espace staff.';
  $('deleteMyCharacter').disabled=false;
  button.disabled=deleteInput.value.trim()!=='SUPPRIMER';
 }
};
try{const previous=sessionStorage.getItem(accountModeKey);if(['guest','participant'].includes(previous))selectGameMode(previous)}catch{}



// Réglages personnels : préférences strictement locales, sans incidence sur la progression serveur.
const playerSettingKey='sf-player-settings-v159';
const defaultPlayerSettings=Object.freeze({view3d:true,cinema:true,relief:true,compact:false,hideRanks:false,hideCompass:false,hideNearby:false,hideHints:false,largeControls:false,zoom:'default',fishMode:'auto',showDuel:true,showDuelScore:true,contrast:false,reduceMotion:false});
const playerSettingsForm=$('playerSettingsForm');
let playerSettings={...defaultPlayerSettings};
function loadPlayerSettings(){try{const old=JSON.parse(localStorage.getItem(playerSettingKey)||'null');if(old&&typeof old==='object'&&!Array.isArray(old))for(const [key,value] of Object.entries(defaultPlayerSettings)){if(typeof value==='boolean'&&typeof old[key]==='boolean')playerSettings[key]=old[key];if(typeof value==='string'&&typeof old[key]==='string'&&(['zoom','fishMode'].includes(key)))playerSettings[key]=old[key]}}catch{}}
function setPlayerSettingsForm(){for(const [key,value] of Object.entries(playerSettings)){const field=playerSettingsForm.elements.namedItem(key);if(!field)continue;if(field.type==='checkbox')field.checked=!!value;else field.value=value}}
function applyPlayerSettings(changedZoom=false){
 setView3d(!!playerSettings.view3d);
 if(playerSettings.relief!==reliefOn){reliefOn=!!playerSettings.relief;detailTiles.clear();detailMips.clear()}
 for(const [key,value] of Object.entries(playerSettings))if(typeof value==='boolean')document.body.dataset['setting'+key[0].toUpperCase()+key.slice(1)]=String(value);
 if(playerSettings.zoom!=='default'&&changedZoom){const values={near:1.6,normal:.9,far:.48};if(values[playerSettings.zoom])setMapZoom(values[playerSettings.zoom]);}
 if(phase==='walk'&&!starting&&fishingMode!==playerSettings.fishMode){const field=$('fishMode');field.value=playerSettings.fishMode;field.dispatchEvent(new Event('change'))}
}
function readPlayerSettingsForm(){for(const key of Object.keys(defaultPlayerSettings)){const field=playerSettingsForm.elements.namedItem(key);if(field)playerSettings[key]=field.type==='checkbox'?field.checked:field.value}}
function savePlayerSettings(){try{localStorage.setItem(playerSettingKey,JSON.stringify(playerSettings));$('settingsStatus').textContent='Préférences enregistrées sur cet appareil.'}catch{$('settingsStatus').textContent='Impossible de conserver les réglages sur cet appareil.'}}
$('playerSettingsBtn').onclick=()=>{if($('menu').open)$('menu').close();setPlayerSettingsForm();openDialog('playerSettings')};
$('hudSettingsBtn').onclick=()=>$('playerSettingsBtn').click();
playerSettingsForm.addEventListener('change',()=>{const previousZoom=playerSettings.zoom;readPlayerSettingsForm();applyPlayerSettings(previousZoom!==playerSettings.zoom);savePlayerSettings()});
playerSettingsForm.addEventListener('submit',event=>{event.preventDefault();readPlayerSettingsForm();applyPlayerSettings(false);savePlayerSettings();$('playerSettings').close()});
$('resetPlayerSettings').onclick=()=>{playerSettings={...defaultPlayerSettings};setPlayerSettingsForm();applyPlayerSettings(false);savePlayerSettings()};
$('resetDuelPosition').onclick=()=>{try{localStorage.removeItem(duelPosKey)}catch{}placeDuel(innerWidth-60,innerHeight*.45,true);$('settingsStatus').textContent='Bouton duel replacé à droite.'};
loadPlayerSettings();
// Respecter le choix existant de mode pêche à la première ouverture des paramètres.
try{if(!localStorage.getItem(playerSettingKey))playerSettings.fishMode=fishingMode}catch{}
setPlayerSettingsForm();applyPlayerSettings(false);
